#import "native_internal.h"

static void SetTooltip(BattMenuController *controller, BattMenuItem item, NSString *tooltip) {
    [controller item:item].toolTip = tooltip;
}

void BattApplyTooltips(BattMenuController *controller) {
    SetTooltip(controller, BattItemPowerFlow, BattT(@"Power flow data is updated every 60 seconds."));
    SetTooltip(controller, BattItemUpgrade, BattT(@"Your batt daemon is not compatible with this client version and needs to be upgraded. This is usually caused by a new client version that requires a new daemon version. You can upgrade the batt daemon by running this command."));
    SetTooltip(controller, BattItemInstall, BattT(@"Install the batt daemon. batt daemon is a component that controls charging. You must enter your password to install it because controlling charging is a privileged action."));
    SetTooltip(controller, BattItemChargeOnce, BattT(@"Charge the battery once without changing your charge limit.\n\n\"Charge to <limit>% Now\" starts charging right away, even when the charge sits between the lower and the upper limit, and stops at the limit.\n\n\"Charge to Full Once\" charges to 100% and then restores your limit automatically.\n\nA one-time charge survives a restart. Cancel it here, or set a charge limit to cancel it."));
    SetTooltip(controller, BattItemMagSafe, BattT(@"Let batt control MagSafe LED to reflect the charging state of your MacBook (or force it off).\n\nNote that you must have a MagSafe LED on your MacBook to use this feature."));
    SetTooltip(controller, BattItemMagSafeEnabled, BattT(@"Enable MagSafe LED control. The LED will reflect charging status:\n\n- Green: Charging is stopped.\n- Orange: Charging is in progress.\n- Off: Forced off, or temporarily after wake with active charging control."));
    SetTooltip(controller, BattItemMagSafeDisabled, BattT(@"Disable MagSafe LED control. The LED will stay in its default state (mostly orange)."));
    SetTooltip(controller, BattItemMagSafeAlwaysOff, BattT(@"Force the MagSafe LED to stay off regardless of charging state."));
    SetTooltip(controller, BattItemPreventIdleSleep, BattT(@"Set whether to prevent idle sleep during a charging session.\n\nDue to macOS limitations, batt will be paused when your computer goes to sleep. As a result, when you are in a charging session and your computer goes to sleep, there is no way for batt to stop charging (since batt is paused by macOS) and the battery will charge to 100%. This option, together with \"Disable Charging before Sleep\", will prevent this from happening.\n\nThis option tells macOS NOT to go to sleep when the computer is in a charging session, so batt can continue to work until charging is finished. Note that it will only prevent **idle** sleep, when 1) charging is active 2) battery charge limit is enabled. So your computer can go to sleep as soon as a charging session is completed.\n\nHowever, this options does not prevent manual sleep (limitation of macOS). For example, if you manually put your computer to sleep (by choosing the Sleep option in the top-left Apple menu) or close the lid, batt will still be paused and the issue mentioned above will still happen. This is where \"Disable Charging before Sleep\" comes in."));
    SetTooltip(controller, BattItemDisableChargingPreSleep, BattT(@"Set whether to disable charging before sleep if charge limit is enabled.\n\nAs described in \"Prevent Idle Sleep when Charging\", batt will be paused by macOS when your computer goes to sleep, and there is no way for batt to continue controlling battery charging. This option will disable charging just before sleep, so your computer will not overcharge during sleep, even if the battery charge is below the limit."));
    SetTooltip(controller, BattItemPreventSystemSleep, BattT(@"Set whether to prevent system sleep during a charging session (experimental).\n\nThis option tells macOS to create power assertion, which prevents sleep, when all conditions are met:\n\n1) charging is active\n2) battery charge limit is enabled\n3) computer is connected to charger.\nSo your computer can go to sleep as soon as a charging session is completed / charger disconnected.\n\nDoes similar thing to prevent-idle-sleep, but works for manual sleep too.\n\nNote: please disable disable-charging-pre-sleep and prevent-idle-sleep, while this feature is in use"));
    SetTooltip(controller, BattItemPreventSleepOnAdapterDisable, BattT(@"Set whether to keep Clamshell mode alive while adapter input is disabled by temporarily disabling system sleep.\n\nThis prevents all sleep—not just idle sleep—while adapter input is disabled, allowing Force Discharge and Auto Calibration to continue with the lid closed. When adapter input returns, batt automatically restores the prior sleep setting.\n\nWARNING: Your Mac may remain awake with the lid closed, overheat in a bag, or drain its battery to 0% if unplugged and left unattended."));
    SetTooltip(controller, BattItemNoDrain, BattT(@"Experimental macOS 27 native-mode option. Hold wall power above the limit instead of draining the battery.\n\nChanging this policy restarts powerd. batt waits for other applications' sleep assertions to end first and uses the regular native limit meanwhile."));
    SetTooltip(controller, BattItemForceDischarge, BattT(@"Cut power from the wall and run from the battery, either indefinitely or for a selected duration. After a temporary force discharge, batt automatically restores the power adapter.\n\nNOTE: if you are using Clamshell mode (using a Mac laptop with an external monitor and the lid closed), *cutting power will cause your Mac to go to sleep* unless \"Prevent Sleep when Adapter is Disabled\" is enabled. This is a limitation of macOS. There are ways to prevent this, but it is not recommended for most users."));
    SetTooltip(controller, BattItemAutoCalibration, BattT(@"Calibration helps you calibrate your battery by automatically discharging and charging it according to best practices.\n\nbatt prevents idle sleep for the entire calibration session. Closing the lid or explicitly choosing Sleep can still force sleep.\n\nIt's recommended to run the calibration process every few months."));
    SetTooltip(controller, BattItemUninstall, BattT(@"Uninstall the batt daemon. This will remove the batt daemon from your system. You must enter your password to uninstall it.\n\nAfter uninstalling the batt daemon, no charging control will be present on your system and your Mac will charge to 100% as normal. The menubar app will still be present, but all options will be disabled. You can remove the menubar app by moving it to the trash."));
    SetTooltip(controller, BattItemDisableLimit, BattT(@"Disable the battery charge limit and let your Mac charge to 100%, either indefinitely or for a selected duration. After a temporary disable, batt automatically restores your current limit."));
    SetTooltip(controller, BattItemQuit, BattT(@"Quit the batt menubar app, but keep the batt daemon running.\n\nSince the batt daemon is still running, batt can continue to control charging. This is useful if you don't want the menubar icon to show up, but still want to use batt. When the client is not running, you can change batt settings using the command line interface (batt). To prevent the menubar app from starting at login, you can remove it in System Settings -> General -> Login Items & Extensions -> remove batt.app from the list (do NOT remove the batt daemon).\n\nIf you want batt to stop controlling charging, you can use the \"Disable Charge Limit\" command. To uninstall, you can use the \"Uninstall Daemon\" command in the Advanced menu."));
}
